class vector3d
{
public:
  float x, y, z;
};

enum WaveRegionEnum
{
  WAVE_REGIONFRONT = 4
};

enum WaveMarkerEnum
{
  WAVE_MarkerInvalid = -1
};

enum WaveQueryFlags
{
  WAVE_YGIVEN = 0x1,
  WAVE_NORMALSOUGHT = 0x2,
  WAVE_HINTGIVEN = 0x4,
  WAVE_HINTSOUGHT = 0x8,
  WAVE_NEARMATCH = 0x10,
  WAVE_CURRENTSOUGHT = 0x20,
  WAVE_REGIONSOUGHT = 0x40,
  WAVE_LIMITSGIVEN = 0x100
};

struct WavePositionHint;

struct WaveTolerance
{
  float dthresh;
  float zthresh;
};

class CollideCallStruct
{
public:
  vector3d position;
  vector3d *normal;
  vector3d *current;
  WaveRegionEnum *region;
  WavePositionHint *hint;
  WaveTolerance tolerance;
};

struct WaveNearestArgs
{
  WaveQueryFlags flags;
  const vector3d &position;
  vector3d *positionout;
  vector3d *normal;
  vector3d *current;
  WaveRegionEnum *region;
  const WavePositionHint &hintin;
  WavePositionHint *hintout;
  const WaveTolerance &tolerance;
  WaveMarkerEnum frontlimit;
  WaveMarkerEnum backlimit;
};

extern float WAVE_MeshMaxX;
extern float WAVE_MeshMinX;
extern float WAVE_MeshMaxZ;
extern float WAVE_MeshMinZ;

bool WAVE_FindNearest(const WaveNearestArgs &args);
float WATER_Altitude(float x, float z);
void WATER_Normal(float x, float z, float &nx, float &ny, float &nz);
void WAVE_GlobalCurrent(vector3d *current);

bool WAVE_CheckCollision (CollideCallStruct & cs, bool hint_valid, bool y_valid, bool near_match, bool limitgiven, WaveMarkerEnum frontlimit, WaveMarkerEnum backlimit)
{
 	bool retval;
 	if ((cs.position.x < WAVE_MeshMaxX) &&
 		(cs.position.x > WAVE_MeshMinX) &&
 		(cs.position.z < WAVE_MeshMaxZ) &&
 		(cs.position.z > WAVE_MeshMinZ))
 	{
 		WaveNearestArgs args = {
 			(WaveQueryFlags) (near_match ? WAVE_NEARMATCH : 0),
 				cs.position,
 				&cs.position,
 				cs.normal,
 				cs.current,
 				cs.region,
 				*cs.hint,
 				cs.hint,
 				cs.tolerance,
 		};

 		if (cs.hint)
 		{
 			args.flags = (WaveQueryFlags)(args.flags | WAVE_HINTSOUGHT);

 			if (hint_valid)
 			{
 				args.flags = (WaveQueryFlags)(args.flags | WAVE_HINTGIVEN);
 			}
 		}

 		if (y_valid)
 			args.flags = (WaveQueryFlags)(args.flags | WAVE_YGIVEN);

 		if (limitgiven)
 		{
 			args.flags = (WaveQueryFlags)(args.flags | WAVE_LIMITSGIVEN);
 			args.frontlimit = frontlimit;
 			args.backlimit = backlimit;
 		}

 		if (cs.normal)
 			args.flags = (WaveQueryFlags)(args.flags | WAVE_NORMALSOUGHT);

 		if (cs.current)
 			args.flags = (WaveQueryFlags)(args.flags | WAVE_CURRENTSOUGHT);

 		if (cs.region)
 			args.flags = (WaveQueryFlags)(args.flags | WAVE_REGIONSOUGHT);

 		retval = WAVE_FindNearest(args);
 	}
 	else
 	{
 		cs.position.y = WATER_Altitude (cs.position.x, cs.position.z);

 		if (cs.normal)
 			WATER_Normal (cs.position.x, cs.position.z, cs.normal->x, cs.normal->y, cs.normal->z);

 		if (cs.current)
 			WAVE_GlobalCurrent (cs.current);

 		if (cs.region)
 			*cs.region = WAVE_REGIONFRONT;

 		return false;
 	}

 	return retval;
}
